import SwiftUI
import Metal
import QuartzCore
import UIKit
import simd

let shaderSource = """
#include <metal_stdlib>
using namespace metal;
struct VertexIn {
    float4 position [[attribute(0)]];
    float2 texCoord [[attribute(1)]];
};
struct VertexOut {
    float4 position [[position]];
    float2 texCoord;
};
struct Uniforms {
    float2 resolution;
    float time;
    float2 touchPos;
    float touchActive;
};
vertex VertexOut vertexMain(uint vertexID [[vertex_id]]) {
    float2 positions[4] = { float2(-1.0, -1.0), float2(1.0, -1.0), float2(-1.0, 1.0), float2(1.0, 1.0) };
    float2 texCoords[4] = { float2(0.0, 1.0), float2(1.0, 1.0), float2(0.0, 0.0), float2(1.0, 0.0) };
    VertexOut out;
    out.position = float4(positions[vertexID], 0.0, 1.0);
    out.texCoord = texCoords[vertexID];
    return out;
}
float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}
float sdRoundRect(float2 p, float2 b, float r) {
    float2 d = abs(p) - b + float2(r);
    return min(max(d.x, d.y), 0.0) + length(max(d, 0.0)) - r;
}
fragment float4 fragmentMain(VertexOut in [[stage_in]], constant Uniforms &uniforms [[buffer(0)]], texture2d<float> backgroundTexture [[texture(0)]]) {
    float2 uv = in.position.xy / uniforms.resolution;
    float2 aspect = float2(uniforms.resolution.x / uniforms.resolution.y, 1.0);
    float2 p = (uv - 0.5) * aspect;
    float2 touchPos = (uniforms.touchPos - 0.5) * aspect;
    float baseShape = sdRoundRect(p, float2(0.3, 0.15), 0.05);
    float touchShape = length(p - touchPos) - 0.08;
    float interaction = uniforms.touchActive * touchShape;
    float finalSDF = smin(baseShape, interaction, 0.1);
    float2 e = float2(0.001, 0.0);
    float nx = smin(sdRoundRect(p + e.xy, float2(0.3, 0.15), 0.05), length(p + e.xy - touchPos) - 0.08, 0.1) - finalSDF;
    float ny = smin(sdRoundRect(p + e.yx, float2(0.3, 0.15), 0.05), length(p + e.yx - touchPos) - 0.08, 0.1) - finalSDF;
    float3 normal = normalize(float3(nx, ny, 0.001));
    float2 refractionUV = uv + normal.xy * 0.05 * smoothstep(0.01, -0.01, finalSDF);
    constexpr sampler texSampler(mag_filter::linear, min_filter::linear);
    float4 bgColor = backgroundTexture.sample(texSampler, refractionUV);
    float luminance = dot(bgColor.rgb, float3(0.299, 0.587, 0.114));
    float3 lightDir = normalize(float3(0.5, 0.5, 1.0));
    float diffuse = max(dot(normal, lightDir), 0.0);
    float3 viewDir = float3(0.0, 0.0, 1.0);
    float3 reflectDir = reflect(-lightDir, normal);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);
    float rim = 1.0 - max(dot(viewDir, normal), 0.0);
    rim = smoothstep(0.6, 1.0, rim);
    float3 glassTint = mix(float3(0.9, 0.9, 0.95), float3(0.2, 0.2, 0.25), step(0.5, luminance));
    float3 finalColor = mix(bgColor.rgb * glassTint + (spec * 0.8) + (rim * 0.3 * (1.0 - luminance)), bgColor.rgb, smoothstep(-0.01, 0.01, finalSDF));
    return float4(finalColor, 1.0);
}
"""

class LiquidPhysicsEngine {
    var position: SIMD2<Float> = .zero
    var velocity: SIMD2<Float> = .zero
    var target: SIMD2<Float> = .zero
    let springConstant: Float = 300.0
    let damping: Float = 20.0
    let mass: Float = 1.0
    func update(dt: Float) {
        let force = springConstant * (target - position) - damping * velocity
        let acceleration = force / mass
        velocity += acceleration * dt
        position += velocity * dt
    }
}

class CALiquidGlassLayer: CAMetalLayer {
    var commandQueue: MTLCommandQueue!
    var pipelineState: MTLRenderPipelineState!
    var displayLink: CADisplayLink!
    var startTime: CFTimeInterval = 0
    let physicsEngine = LiquidPhysicsEngine()
    var touchPosition: SIMD2<Float> = .zero
    var isTouched: Float = 0.0
    override init() {
        super.init()
        setupMetal()
    }
    required init?(coder: NSCoder) {
        super.init(coder: coder)
        setupMetal()
    }
    func setupMetal() {
        device = MTLCreateSystemDefaultDevice()
        pixelFormat = .bgra8Unorm
        framebufferOnly = true
        commandQueue = device?.makeCommandQueue()
        let library = try! device?.makeLibrary(source: shaderSource, options: nil)
        let vertexFunction = library?.makeFunction(name: "vertexMain")
        let fragmentFunction = library?.makeFunction(name: "fragmentMain")
        let pipelineDescriptor = MTLRenderPipelineDescriptor()
        pipelineDescriptor.vertexFunction = vertexFunction
        pipelineDescriptor.fragmentFunction = fragmentFunction
        pipelineDescriptor.colorAttachments[0].pixelFormat = pixelFormat
        pipelineState = try! device?.makeRenderPipelineState(descriptor: pipelineDescriptor)
        startTime = CACurrentMediaTime()
        displayLink = CADisplayLink(target: self, selector: #selector(render))
        displayLink.add(to: .main, forMode: .common)
    }
    @objc func render() {
        guard let drawable = nextDrawable() else { return }
        physicsEngine.target = touchPosition
        physicsEngine.update(dt: 1.0 / 60.0)
        let renderPassDescriptor = MTLRenderPassDescriptor()
        renderPassDescriptor.colorAttachments[0].texture = drawable.texture
        renderPassDescriptor.colorAttachments[0].loadAction = .clear
        renderPassDescriptor.colorAttachments[0].clearColor = MTLClearColor(red: 0, green: 0, blue: 0, alpha: 0)
        let commandBuffer = commandQueue.makeCommandBuffer()!
        let renderEncoder = commandBuffer.makeRenderCommandEncoder(descriptor: renderPassDescriptor)!
        renderEncoder.setRenderPipelineState(pipelineState)
        var resolution = SIMD2<Float>(Float(bounds.width * contentsScale), Float(bounds.height * contentsScale))
        var time = Float(CACurrentMediaTime() - startTime)
        var touchPos = SIMD2<Float>(physicsEngine.position.x / Float(bounds.width), physicsEngine.position.y / Float(bounds.height))
        var active = isTouched
        let uniformsBuffer = device?.makeBuffer(length: MemoryLayout<SIMD2<Float>>.size * 2 + MemoryLayout<Float>.size * 2, options: [])
        let contents = uniformsBuffer?.contents()
        contents?.storeBytes(of: resolution, toByteOffset: 0, as: SIMD2<Float>.self)
        contents?.storeBytes(of: time, toByteOffset: MemoryLayout<SIMD2<Float>>.size, as: Float.self)
        contents?.storeBytes(of: touchPos, toByteOffset: MemoryLayout<SIMD2<Float>>.size + MemoryLayout<Float>.size, as: SIMD2<Float>.self)
        contents?.storeBytes(of: active, toByteOffset: MemoryLayout<SIMD2<Float>>.size + MemoryLayout<Float>.size + MemoryLayout<SIMD2<Float>>.size, as: Float.self)
        renderEncoder.setFragmentBuffer(uniformsBuffer, offset: 0, index: 0)
        renderEncoder.drawPrimitives(type: .triangleStrip, vertexStart: 0, vertexCount: 4)
        renderEncoder.endEncoding()
        commandBuffer.present(drawable)
        commandBuffer.commit()
    }
    override func touchesBegan(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard let touch = touches.first else { return }
        let loc = touch.location(in: nil)
        touchPosition = SIMD2<Float>(Float(loc.x), Float(loc.y))
        physicsEngine.position = touchPosition
        isTouched = 1.0
    }
    override func touchesMoved(_ touches: Set<UITouch>, with event: UIEvent?) {
        guard let touch = touches.first else { return }
        let loc = touch.location(in: nil)
        touchPosition = SIMD2<Float>(Float(loc.x), Float(loc.y))
    }
    override func touchesEnded(_ touches: Set<UITouch>, with event: UIEvent?) {
        isTouched = 0.0
    }
}

struct GlassModifier: ViewModifier {
    func body(content: Content) -> some View {
        content.overlay(LiquidGlassView())
    }
}

extension View {
    func glassEffect() -> some View {
        self.modifier(GlassModifier())
    }
}

struct LiquidGlassView: UIViewRepresentable {
    func makeUIView(context: Context) -> UIView {
        let view = UIView()
        let layer = CALiquidGlassLayer()
        layer.frame = UIScreen.main.bounds
        view.layer.addSublayer(layer)
        return view
    }
    func updateUIView(_ uiView: UIView, context: Context) {}
}

struct GlassEffectContainer<Content: View>: View {
    let content: Content
    init(@ViewBuilder content: () -> Content) {
        self.content = content()
    }
    var body: some View {
        ZStack {
            content
        }.glassEffect()
    }
}
