<script>
// --- WebGL LIQUID GLASS ENGINE ---
const canvas = document.getElementById('glass-renderer-canvas');
const gl = canvas.getContext('webgl2', { alpha: true, antialias: true, premultipliedAlpha: true });

const VS = `#version 300 es
in vec4 aVertexPosition;
out vec2 vUv;
void main() {
    vUv = aVertexPosition.xy * 0.5 + 0.5;
    vUv.y = 1.0 - vUv.y;
    gl_Position = aVertexPosition;
}`;

// The abstract dynamic background
const BG_FS = `#version 300 es
precision highp float;
in vec2 vUv;
out vec4 fragColor;
uniform vec2 uRes;
uniform float uTime;

vec3 pal(float t) {
    return vec3(0.5,0.5,0.5) + vec3(0.5,0.5,0.5)*cos(6.28318*(vec3(1.0,1.0,1.0)*t+vec3(0.0,0.33,0.67)));
}

void main() {
    vec2 p = (vUv - 0.5) * vec2(uRes.x/uRes.y, 1.0);
    float t = uTime * 0.2;
    vec3 c = vec3(0.0);
    for(int i=0; i<3; i++) {
        float f = float(i);
        vec2 d = vec2(sin(t*0.5+f), cos(t*0.3+f)) * 0.4;
        float m = smoothstep(0.8, 0.0, length(p-d));
        c += pal(f*0.2 + t*0.1) * m * 0.5;
    }
    fragColor = vec4(c * 0.3, 1.0); // Kept dark to match theme
}`;

// The Refractive Compositor (This reads all .lg DOM elements and merges them in SDF)
const MAIN_FS = `#version 300 es
precision highp float;
in vec2 vUv;
out vec4 fragColor;

uniform sampler2D uBg;
uniform vec2 uRes;
uniform float uTime;
uniform vec2 uMouse;

// We pass the DOM rects of all .lg elements here
uniform int uShapeCount;
uniform vec4 uRects[30]; // x, y, w, h
uniform float uRadii[30]; // border-radius

// SDF for Rounded Rect
float sdRoundRect(vec2 p, vec2 b, float r) {
    vec2 q = abs(p) - b + vec2(r);
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r;
}

// Smooth min for Metaball effect
float smin(float a, float b, float k) {
    float h = clamp(0.5 + 0.5 * (b - a) / k, 0.0, 1.0);
    return mix(b, a, h) - k * h * (1.0 - h);
}

float sceneSDF(vec2 px) {
    float d = 1e9;
    for(int i=0; i<30; i++) {
        if(i >= uShapeCount) break;
        vec4 r = uRects[i];
        vec2 center = r.xy + r.zw * 0.5;
        vec2 halfSize = r.zw * 0.5;
        float sd = sdRoundRect(px - center, halfSize, uRadii[i]);
        // Merge with smin for the liquid fluid feeling
        d = smin(d, sd, 25.0); 
    }
    // Add Mouse interaction spring dent
    float mouseSDF = length(px - uMouse) - 40.0;
    d = smin(d, mouseSDF, 60.0);
    return d;
}

void main() {
    vec2 px = vUv * uRes; // Pixel coordinates
    float d = sceneSDF(px);

    // Calculate Normal from SDF
    vec2 e = vec2(1.0, 0.0);
    float nx = sceneSDF(px + e.xy) - d;
    float ny = sceneSDF(px + e.yx) - d;
    vec3 normal = normalize(vec3(nx, ny, 15.0)); // Z controls flatness

    // Base Background
    vec3 rawBg = texture(uBg, vUv).rgb;

    if(d > 0.0) {
        // Outside of glass
        float shadow = smoothstep(0.0, 15.0, d);
        fragColor = vec4(rawBg * mix(0.5, 1.0, shadow), 1.0);
        return;
    }

    // Inside Liquid Glass
    float glassMask = smoothstep(0.0, -1.0, d);

    // Refraction UV distortion
    float refStr = 0.03;
    vec2 refUV = vUv - (normal.xy * refStr);
    vec3 refBg = texture(uBg, refUV).rgb;

    // Chromatic Aberration (Split RGB channels slightly)
    vec3 caBg;
    caBg.r = texture(uBg, vUv - (normal.xy * (refStr + 0.005))).r;
    caBg.g = refBg.g;
    caBg.b = texture(uBg, vUv - (normal.xy * (refStr - 0.005))).b;

    // Frosting & Tint
    vec3 tint = vec3(0.05, 0.1, 0.2); // Dark iOS glass
    vec3 frosted = mix(caBg, tint, 0.6);

    // Lighting & Specular
    vec3 lightDir = normalize(vec3(0.3, 0.5, 1.0));
    vec3 viewDir = vec3(0.0, 0.0, 1.0);
    vec3 reflectDir = reflect(-lightDir, normal);
    float spec = pow(max(dot(viewDir, reflectDir), 0.0), 32.0);

    // Rim Light
    float rim = 1.0 - max(dot(viewDir, normal), 0.0);
    rim = smoothstep(0.5, 1.0, rim) * 0.4;

    vec3 finalMat = frosted + vec3(spec * 0.7) + vec3(rim);

    // Edge Anti-aliasing
    vec3 comp = mix(rawBg, finalMat, glassMask);

    // Inner border stroke
    float border = smoothstep(-1.0, -2.0, d) - smoothstep(-2.0, -3.0, d);
    comp += vec3(border * 0.15);

    fragColor = vec4(comp, 1.0);
}`;

function createShader(gl, type, source) {
    const s = gl.createShader(type);
    gl.shaderSource(s, source);
    gl.compileShader(s);
    return s;
}

function createProgram(gl, vs, fs) {
    const p = gl.createProgram();
    gl.attachShader(p, createShader(gl, gl.VERTEX_SHADER, vs));
    gl.attachShader(p, createShader(gl, gl.FRAGMENT_SHADER, fs));
    gl.linkProgram(p);
    return p;
}

const bgProg = createProgram(gl, VS, BG_FS);
const mainProg = createProgram(gl, VS, MAIN_FS);

const posBuffer = gl.createBuffer();
gl.bindBuffer(gl.ARRAY_BUFFER, posBuffer);
gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1,-1, 1,-1, -1,1, 1,1]), gl.STATIC_DRAW);

// FBO for background
let bgTex, bgFB;
function initFBO() {
    if(bgTex) gl.deleteTexture(bgTex);
    if(bgFB) gl.deleteFramebuffer(bgFB);
    bgTex = gl.createTexture();
    gl.bindTexture(gl.TEXTURE_2D, bgTex);
    gl.texImage2D(gl.TEXTURE_2D, 0, gl.RGBA16F, canvas.width, canvas.height, 0, gl.RGBA, gl.HALF_FLOAT, null);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MIN_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_MAG_FILTER, gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_S, gl.CLAMP_TO_EDGE);
    gl.texParameteri(gl.TEXTURE_2D, gl.TEXTURE_WRAP_T, gl.CLAMP_TO_EDGE);
    bgFB = gl.createFramebuffer();
    gl.bindFramebuffer(gl.FRAMEBUFFER, bgFB);
    gl.framebufferTexture2D(gl.FRAMEBUFFER, gl.COLOR_ATTACHMENT0, gl.TEXTURE_2D, bgTex, 0);
}

function resize() {
    canvas.width = window.innerWidth * window.devicePixelRatio;
    canvas.height = window.innerHeight * window.devicePixelRatio;
    gl.viewport(0, 0, canvas.width, canvas.height);
    initFBO();
}
window.addEventListener('resize', resize);
resize();

// DOM Sync
let rects = new Float32Array(30 * 4);
let radii = new Float32Array(30);
let shapeCount = 0;

let mx = -1000, my = -1000;
window.addEventListener('pointermove', e => {
    mx = e.clientX * window.devicePixelRatio;
    my = e.clientY * window.devicePixelRatio;
});

function syncDOM() {
    const els = document.querySelectorAll('.lg');
    shapeCount = 0;
    for(let i = 0; i < els.length && i < 30; i++) {
        const rect = els[i].getBoundingClientRect();
        if(rect.width === 0 || rect.height === 0 || window.getComputedStyle(els[i]).display === 'none') continue;

        rects[shapeCount*4 + 0] = rect.left * window.devicePixelRatio;
        rects[shapeCount*4 + 1] = rect.top * window.devicePixelRatio;
        rects[shapeCount*4 + 2] = rect.width * window.devicePixelRatio;
        rects[shapeCount*4 + 3] = rect.height * window.devicePixelRatio;

        const style = window.getComputedStyle(els[i]);
        radii[shapeCount] = parseFloat(style.borderTopLeftRadius) * window.devicePixelRatio || 0;
        shapeCount++;
    }
}

function render(time) {
    syncDOM();

    // Pass 1: Render BG
    gl.bindFramebuffer(gl.FRAMEBUFFER, bgFB);
    gl.useProgram(bgProg);
    const bgPos = gl.getAttribLocation(bgProg, "aVertexPosition");
    gl.enableVertexAttribArray(bgPos);
    gl.vertexAttribPointer(bgPos, 2, gl.FLOAT, false, 0, 0);
    gl.uniform2f(gl.getUniformLocation(bgProg, "uRes"), canvas.width, canvas.height);
    gl.uniform1f(gl.getUniformLocation(bgProg, "uTime"), time * 0.001);
    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);

    // Pass 2: Main Compositor
    gl.bindFramebuffer(gl.FRAMEBUFFER, null);
    gl.useProgram(mainProg);
    const mainPos = gl.getAttribLocation(mainProg, "aVertexPosition");
    gl.enableVertexAttribArray(mainPos);
    gl.vertexAttribPointer(mainPos, 2, gl.FLOAT, false, 0, 0);

    gl.activeTexture(gl.TEXTURE0);
    gl.bindTexture(gl.TEXTURE_2D, bgTex);
    gl.uniform1i(gl.getUniformLocation(mainProg, "uBg"), 0);

    gl.uniform2f(gl.getUniformLocation(mainProg, "uRes"), canvas.width, canvas.height);
    gl.uniform1f(gl.getUniformLocation(mainProg, "uTime"), time * 0.001);
    gl.uniform2f(gl.getUniformLocation(mainProg, "uMouse"), mx, my);

    gl.uniform1i(gl.getUniformLocation(mainProg, "uShapeCount"), shapeCount);
    if(shapeCount > 0) {
        gl.uniform4fv(gl.getUniformLocation(mainProg, "uRects"), rects);
        gl.uniform1fv(gl.getUniformLocation(mainProg, "uRadii"), radii);
    }

    gl.drawArrays(gl.TRIANGLE_STRIP, 0, 4);
    requestAnimationFrame(render);
}
requestAnimationFrame(render);

// Interaction simulation for demo
document.addEventListener('keydown', (e) => {
    if(e.key === 'r') {
        const panel = document.getElementById('robot-panel');
        if(panel.getAttribute('aria-hidden') === 'true') {
            panel.setAttribute('aria-hidden', 'false');
            panel.style.opacity = '1';
        } else {
            panel.setAttribute('aria-hidden', 'true');
            panel.style.opacity = '0';
        }
    }
});
</script>
